import React from "react";
import { Link } from "react-router-dom";

const Navbar: React.FC = () => {
  return (
    <div className="fixed top-0 right-0 h-full w-64 bg-gray-800 text-white flex flex-col">
      <div className="p-4 text-lg font-bold">My App</div>
      <nav className="flex-1 flex flex-col">
        <Link to="/" className="px-4 py-2 hover:bg-gray-700">
          Home
        </Link>
        <Link to="/login" className="px-4 py-2 hover:bg-gray-700">
          Login
        </Link>
        <Link to="/users" className="px-4 py-2 hover:bg-gray-700">
          Users List
        </Link>
      </nav>
    </div>
  );
};

export default Navbar;
